function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';

  // book
  ctx.fillStyle = 'black';
  ctx.fillRect(W/2-50, H/2-50, 100, 100);
  ctx.strokeRect(W/2-50, H/2-50, 100, 100);

  // knowledge contained (lines)
  for (let i = 0; i < 10; i++) {
    ctx.beginPath();
    ctx.moveTo(W/2-40, H/2-40 + i*10);
    ctx.lineTo(W/2-20 + 20*Math.sin(t+i), H/2-40 + i*10);
    ctx.stroke();
  }

  ctx.restore();
}
